package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.OperationsDtos.*; import com.vynedam.stockai.model.ProductionRun; import com.vynedam.stockai.security.CurrentUser; import com.vynedam.stockai.service.ProductionService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/production-runs")public class ProductionController{private final ProductionService s;private final CurrentUser u;public ProductionController(ProductionService x,CurrentUser y){s=x;u=y;}@GetMapping List<ProductionRun>list(){return s.list();}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','PRODUCTION_MANAGER')")ResponseEntity<ProductionRun>start(@Valid@RequestBody ProductionRunRequest r,Authentication a){return ResponseEntity.status(201).body(s.start(r,u.id(a)));}@PostMapping("/{id}/complete")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PRODUCTION_MANAGER')")ProductionRun complete(@PathVariable String id,@Valid@RequestBody CompleteRunRequest r,Authentication a){return s.complete(id,r,u.id(a));}}
